from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
main_path = ROOT / "app" / "main.py"

if not main_path.exists():
    raise SystemExit("ERROR: app/main.py not found.")

text = main_path.read_text(encoding="utf-8")

cleaned_lines = []
for line in text.splitlines():
    stripped = line.strip()
    if stripped == "from .paste_router import router as paste_analysis_router":
        continue
    if stripped == "app.include_router(paste_analysis_router)":
        continue
    cleaned_lines.append(line)

text = "\n".join(cleaned_lines).rstrip() + "\n"

marker = "# === V03B DIRECT SMART PASTE ROUTES ==="

if marker not in text:
    text = text.rstrip() + "\n\n" + '\n# === V03B DIRECT SMART PASTE ROUTES ===\nfrom datetime import datetime as _paste_datetime\nfrom uuid import uuid4 as _paste_uuid4\n\nfrom .analyzer import analyze_text as _analyze_text\n\n\ndef _paste_lines(value: str) -> list[str]:\n    return [line.strip() for line in value.splitlines() if line.strip()]\n\n\ndef _paste_semi(value: str) -> list[str]:\n    return [\n        item.strip()\n        for item in value.replace("；", ";").split(";")\n        if item.strip()\n    ]\n\n\n@app.get("/analyze/paste", response_class=HTMLResponse)\ndef smart_paste_page(request: Request):\n    return templates.TemplateResponse(\n        request=request,\n        name="paste_analyze.html",\n        context={"error": None},\n    )\n\n\n@app.post("/analyze/paste/preview", response_class=HTMLResponse)\ndef smart_paste_preview(\n    request: Request,\n    text: str = Form(...),\n    source_type: str = Form("人工录入"),\n    source_url: str = Form(""),\n    visibility: str = Form("内部"),\n):\n    text = text.strip()\n    if len(text) < 20:\n        return templates.TemplateResponse(\n            request=request,\n            name="paste_analyze.html",\n            context={"error": "请至少粘贴20个字符。"},\n            status_code=400,\n        )\n\n    result = _analyze_text(text, source_type)\n\n    return templates.TemplateResponse(\n        request=request,\n        name="paste_preview.html",\n        context={\n            "result": result,\n            "raw_text": text,\n            "source_type": source_type,\n            "source_url": source_url,\n            "visibility": visibility,\n        },\n    )\n\n\n@app.post("/analyze/paste/confirm")\ndef smart_paste_confirm(\n    title: str = Form(...),\n    event_date: str = Form(""),\n    organizations: str = Form(""),\n    event_type: str = Form("其他"),\n    industry_tags: str = Form(""),\n    amount: str = Form(""),\n    facts: str = Form(""),\n    potential_needs: str = Form(""),\n    recommended_actions: str = Form(""),\n    source_grade: str = Form("D"),\n    confidence: str = Form("0"),\n    review_reasons: str = Form(""),\n    raw_text: str = Form(...),\n    source_type: str = Form("人工录入"),\n    source_url: str = Form(""),\n    visibility: str = Form("内部"),\n    create_event: str | None = Form(None),\n    create_organization: str | None = Form(None),\n    create_action: str | None = Form(None),\n    db: Session = Depends(get_db),\n):\n    intelligence = RawIntelligence(\n        title=title.strip() or "未命名情报",\n        source_url=source_url.strip() or None,\n        source_type=source_type,\n        content=raw_text,\n        visibility=visibility,\n        review_status="待审核",\n    )\n    db.add(intelligence)\n\n    event_external_id = None\n\n    if create_event:\n        event_external_id = (\n            f"EVT-AUTO-{_paste_datetime.now():%Y%m%d%H%M%S}-"\n            f"{_paste_uuid4().hex[:4].upper()}"\n        )\n\n        fact_list = _paste_lines(facts)\n        summary_parts = list(fact_list)\n        if amount.strip():\n            summary_parts.append(f"涉及金额：{amount.strip()}")\n\n        event = HistoricalEvent(\n            external_id=event_external_id,\n            event_date=event_date.strip() or None,\n            name=title.strip() or "自动分析事件",\n            event_type=event_type.strip() or "其他",\n            related_entity=None,\n            fact_summary="\\n".join(summary_parts),\n            system_use=(\n                "潜在需求："\n                + "；".join(_paste_semi(potential_needs))\n                + "\\n建议动作："\n                + "\\n".join(_paste_lines(recommended_actions))\n                + f"\\n来源等级：{source_grade}；分析置信度：{confidence}"\n                + "\\n人工复核原因："\n                + "\\n".join(_paste_lines(review_reasons))\n            ),\n            visibility=visibility,\n            verification_status="待核验",\n        )\n        db.add(event)\n\n    if create_organization:\n        for org_name in _paste_lines(organizations):\n            existing = db.scalar(\n                select(Organization).where(\n                    Organization.standard_name == org_name\n                )\n            )\n            if existing:\n                continue\n\n            db.add(\n                Organization(\n                    external_id=(\n                        f"ORG-AUTO-{_paste_uuid4().hex[:10].upper()}"\n                    ),\n                    standard_name=org_name,\n                    org_type="待分类",\n                    region=None,\n                    industry_tags=(\n                        "；".join(_paste_semi(industry_tags)) or None\n                    ),\n                    resources=None,\n                    needs=(\n                        "；".join(_paste_semi(potential_needs)) or None\n                    ),\n                    relationship_source="粘贴自动分析",\n                    visibility=visibility,\n                    verification_status="待核验",\n                )\n            )\n\n    if create_action:\n        actions = _paste_lines(recommended_actions)\n        if not actions:\n            actions = ["人工复核该条情报并确认下一步。"]\n\n        for action_text in actions[:5]:\n            db.add(\n                ActionItem(\n                    external_id=(\n                        f"ACT-AUTO-{_paste_uuid4().hex[:10].upper()}"\n                    ),\n                    task=action_text,\n                    target_external_id=event_external_id,\n                    completion_standard=(\n                        "完成需求核实、证据补充或资源对接，并记录结果。"\n                    ),\n                    owner="项目负责人",\n                    priority="P1",\n                    status="未开始",\n                    suggested_deadline=None,\n                )\n            )\n\n    db.commit()\n    return RedirectResponse(url="/intelligence", status_code=303)\n'.strip() + "\n"
    main_path.write_text(text, encoding="utf-8")
    print("DIRECT ROUTE FIX APPLIED")
else:
    print("DIRECT ROUTE FIX ALREADY PRESENT")
